package com.faraz.expensemanagement.repo; import com.faraz.expensemanagement.entity.*; import java.util.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.time.*; import java.math.*; public interface TxRepo extends JpaRepository<Transaction,Long>{List<Transaction> findByUserOrderByTransactionDateDesc(User u);List<Transaction> findTop10ByUserOrderByTransactionDateDesc(User u);Optional<Transaction> findByIdAndUser(Long id,User u);@Query("select coalesce(sum(t.amount),0) from Transaction t where t.user=:u and t.type=:type and t.transactionDate between :f and :to")BigDecimal sum(@Param("u")User u,@Param("type")Transaction.Type type,@Param("f")LocalDate f,@Param("to")LocalDate to);}
